#include <bits/stdc++.h>using namespace std;#define int long longstring s,ans_last;int len,T,sum;vector<int> ans_pre; int calc(int num){    string ss = to_string(num);    int res = 0;    for(char &c : ss){        res += c - '0';    }    return res;} void O_o(){    vector<int> cnt(10,0);    sum = 0;    cin >> s;    len = s.size();    if(len == 1){        cout << s << '\n';        return ;    }    for(char &c : s){        sum += c - '0';        cnt[c - '0']++;    }    for(int i=1;i<=len * 9;i++){        bool ok = 1;        string last = "";        int x = i;        while(x > 9){            last += to_string(x);            x = calc(x);        }        last += to_string(x);        x = i;         //check for last        vector<int> cnt_it(10,0);        for(char &c : last){            cnt_it[c - '0']++;        }        for(int j=0;j<=9;j++){            if(cnt[j] < cnt_it[j]){                ok = 0;                break;            }        }        if(!ok)continue;         //check for front        int pre_sum = 0;        for(int j=0;j<=9;j++){            pre_sum += j * (cnt[j] - cnt_it[j]);        }        if(pre_sum == i){            ans_last = last;            ans_pre = cnt_it;            break;        }    }    vector<int> pre;    for(int i=0;i<=9;i++){        for(int j=1;j<=cnt[i] - ans_pre[i];j++){            pre.emplace_back(i);        }    }    string pre_s = "";    sort(pre.rbegin(),pre.rend());    for(auto &x : pre){        pre_s += to_string(x);    }    pre_s += ans_last;    cout << pre_s << '\n';} signed main(){    ios::sync_with_stdio(false);    cin.tie(nullptr);cout.tie(nullptr);    cin >> T;    while(T--)O_o();    return 0;}